// OWNER: QA-06
//
// The eval set manifest (tool/eval/eval_set.json, ai.md §16.5). Every clip names its language,
// kind (speech or a non-speech kind for the hallucination check), source and licence. Allowed
// licences: CC0-1.0 (Common Voice), CC-BY-4.0 (FLEURS, attribution required), public-domain
// (LibriVox, US government works), in-house (Danaview screen recordings). Remote clips are pinned by
// URL, byte size and sha256 and fetched into the clip cache by scripts/ci/editor/nightly.d/ai_eval.sh;
// synthetic clips are generated by the harness; repo clips are files in this repository.

import 'dart:convert';
import 'dart:io';

import 'package:danaview_transcription/danaview_transcription.dart';
import 'package:path/path.dart' as p;

import 'synth_audio.dart';
import 'timing.dart';

/// Licences the eval set may use.
const Set<String> allowedLicences = {'CC0-1.0', 'CC-BY-4.0', 'public-domain', 'in-house'};

/// What a clip contains.
enum ClipKind {
  /// Speech with a reference transcript.
  speech,

  /// Silence (hallucination check).
  silence,

  /// Noise or room tone (hallucination check).
  noise,

  /// Instrumental music (hallucination check).
  music;

  /// Whether the clip has no speech (every recognised word is a hallucination).
  bool get isNonSpeech => this != ClipKind.speech;
}

/// Where a clip's audio comes from.
enum ClipSource {
  /// A file in this repository ([EvalClip.path], relative to the manifest).
  repo,

  /// Generated by the harness ([EvalClip.synth]).
  synthetic,

  /// Downloaded and pinned ([EvalClip.url], [EvalClip.sha256], [EvalClip.bytes]).
  remote,
}

/// A reference transcript, optionally with human-timed cues.
final class ClipReference {
  /// Creates a reference.
  const ClipReference({required this.text, this.cues = const []});

  /// Reads `{"text": "...", "cues": [{"start", "end", "text"}]}`.
  factory ClipReference.fromJson(Map<String, Object?> json) => ClipReference(
        text: (json['text'] as String?) ?? '',
        cues: [
          for (final c in (json['cues'] as List<Object?>?) ?? const <Object?>[]) TimedCue.fromJson(c! as Map<String, Object?>),
        ],
      );

  /// Verbatim reference transcript.
  final String text;

  /// Human-timed cues (empty when the clip has no timing reference).
  final List<TimedCue> cues;
}

/// One eval clip.
final class EvalClip {
  /// Creates a clip.
  const EvalClip({
    required this.id,
    required this.language,
    required this.kind,
    required this.source,
    required this.licence,
    this.attribution = '',
    this.path,
    this.url,
    this.sha256,
    this.bytes,
    this.synth,
    this.reference,
  });

  /// Stable id (`<lang>-<source>-<n>`); also the cache file name.
  final String id;

  /// whisper language code passed to the decoder (explicit language, never detection).
  final String language;

  /// Content kind.
  final ClipKind kind;

  /// Audio source.
  final ClipSource source;

  /// Licence id (one of [allowedLicences]).
  final String licence;

  /// Attribution line (required for CC-BY-4.0; listed in the eval README).
  final String attribution;

  /// Repo clip path, relative to the manifest directory.
  final String? path;

  /// Remote clip URL (https).
  final String? url;

  /// Pinned sha256 of the downloaded file (remote) or of the repo file.
  final String? sha256;

  /// Pinned byte size of the downloaded file.
  final int? bytes;

  /// Synthetic recipe.
  final SynthSpec? synth;

  /// Reference transcript (speech clips).
  final ClipReference? reference;
}

/// The parsed manifest.
final class EvalManifest {
  /// Creates a manifest.
  const EvalManifest({required this.clips, required this.directory});

  /// Parses [json] read from a manifest in [directory] (references resolve against it).
  factory EvalManifest.parse(String json, {required String directory}) {
    final doc = jsonDecode(json);
    if (doc is! Map<String, Object?> || doc['schema'] != 1) throw const FormatException('eval manifest: schema 1 expected');
    final list = doc['clips'];
    if (list is! List<Object?>) throw const FormatException('eval manifest: clips[] missing');
    final clips = <EvalClip>[];
    final ids = <String>{};
    for (final raw in list) {
      if (raw is! Map<String, Object?>) throw const FormatException('eval manifest: clip must be an object');
      final clip = _clip(raw, directory);
      if (!ids.add(clip.id)) throw FormatException('eval manifest: duplicate id ${clip.id}');
      clips.add(clip);
    }
    return EvalManifest(clips: List.unmodifiable(clips), directory: directory);
  }

  /// Loads the manifest at [path].
  static EvalManifest load(String path) =>
      EvalManifest.parse(File(path).readAsStringSync(), directory: p.dirname(p.absolute(path)));

  /// Clips in manifest order.
  final List<EvalClip> clips;

  /// Directory the manifest was read from.
  final String directory;

  /// Languages with speech clips, sorted.
  List<String> get speechLanguages =>
      ({for (final c in clips) if (c.kind == ClipKind.speech) c.language}.toList()..sort());
}

final RegExp _id = RegExp(r'^[a-z0-9][a-z0-9_-]{1,63}$');
final RegExp _sha = RegExp(r'^[0-9a-f]{64}$');

EvalClip _clip(Map<String, Object?> raw, String directory) {
  String need(String key) {
    final v = raw[key];
    if (v is! String || v.isEmpty) throw FormatException('eval manifest: ${raw['id'] ?? '?'}: "$key" missing');
    return v;
  }

  final id = need('id');
  if (!_id.hasMatch(id)) throw FormatException('eval manifest: bad id "$id"');
  final language = need('language');
  if (languageForWhisperCode(language) == null) throw FormatException('eval manifest: $id: unknown language $language');
  final kind = ClipKind.values.where((k) => k.name == raw['kind']).firstOrNull;
  if (kind == null) throw FormatException('eval manifest: $id: bad kind ${raw['kind']}');
  final source = ClipSource.values.where((s) => s.name == raw['source']).firstOrNull;
  if (source == null) throw FormatException('eval manifest: $id: bad source ${raw['source']}');
  final licence = need('licence');
  if (!allowedLicences.contains(licence)) throw FormatException('eval manifest: $id: licence $licence not allowed');
  final attribution = (raw['attribution'] as String?) ?? '';
  if (licence == 'CC-BY-4.0' && attribution.isEmpty) throw FormatException('eval manifest: $id: CC-BY-4.0 needs attribution');

  final sha = raw['sha256'] as String?;
  if (sha != null && !_sha.hasMatch(sha)) throw FormatException('eval manifest: $id: sha256 must be 64 lowercase hex');
  String? path;
  String? url;
  int? bytes;
  SynthSpec? synth;
  switch (source) {
    case ClipSource.repo:
      path = need('path');
      if (sha == null) throw FormatException('eval manifest: $id: repo clips are pinned by sha256');
    case ClipSource.synthetic:
      final s = raw['synth'];
      if (s is! Map<String, Object?>) throw FormatException('eval manifest: $id: synth recipe missing');
      synth = SynthSpec.fromJson(s);
      if (kind == ClipKind.speech) throw FormatException('eval manifest: $id: synthetic clips are non-speech');
    case ClipSource.remote:
      url = need('url');
      if (!url.startsWith('https://')) throw FormatException('eval manifest: $id: remote url must be https');
      bytes = (raw['bytes'] as num?)?.toInt();
      if (sha == null || bytes == null || bytes <= 0) {
        throw FormatException('eval manifest: $id: remote clips are pinned by sha256 and bytes');
      }
  }

  ClipReference? reference;
  final ref = raw['reference'];
  if (ref is String) {
    final file = File(p.join(directory, ref));
    if (!file.existsSync()) throw FormatException('eval manifest: $id: reference $ref not found');
    reference = ClipReference.fromJson(jsonDecode(file.readAsStringSync()) as Map<String, Object?>);
  } else if (ref is Map<String, Object?>) {
    reference = ClipReference.fromJson(ref);
  }
  if (kind == ClipKind.speech && (reference == null || reference.text.trim().isEmpty)) {
    throw FormatException('eval manifest: $id: speech clips need a reference transcript');
  }
  return EvalClip(
    id: id,
    language: language,
    kind: kind,
    source: source,
    licence: licence,
    attribution: attribution,
    path: path,
    url: url,
    sha256: sha,
    bytes: bytes,
    synth: synth,
    reference: reference,
  );
}
